/* v2.4: beginner explanations, examples and glossary */
window.LESSONS.beginner = {
  "a01": "psqlは、PostgreSQLに話しかけるためのアプリです。-Uの後ろにユーザー名、-dの後ろに接続したいデータベース名を書きます。Linuxのターミナルで実行すると、SQLを入力できる画面に入ります。",
  "a02": "テーブルとは、Excelの表のようにデータを行と列で保存するものです。\\dtを入力すると、今のDBで見えるテーブル名が一覧になります。",
  "a03": "\\d usersはusersという表の設計図を見る操作です。列名、データ型、必須項目、インデックスなどを確認できます。",
  "a04": "1つのPostgreSQLサーバーには複数のデータベースを作れます。\\lはその名前の一覧を表示します。",
  "a05": "ロールとは、DBのユーザーや権限をまとめるための仕組みです。\\duで名前と属性を一覧表示します。",
  "a06": "シーケンスは、IDなどに使う連番を作る仕組みです。\\dsでその一覧を表示します。",
  "a07": "\\cはconnectの略です。psqlを閉じず、別のDBに接続し直せます。今のDBから移動するイメージです。",
  "a08": "\\qはquitの略です。psqlだけを終了し、Linuxのターミナルに戻ります。DBサーバー自体は止まりません。",
  "a09": "initdbはDBクラスタ（複数のDBをまとめて管理する保存場所）を新しく用意します。-Dで保存場所を指定します。作っただけでは起動しません。",
  "a10": "pg_ctlはPostgreSQLサーバーの起動・停止などを管理するコマンドです。statusは、指定したクラスタが動いているかを調べます。",
  "a11": "startはPostgreSQLを起動します。-Dで対象クラスタを指定します。起動すると、そのクラスタにあるDBへ接続できるようになります。",
  "a12": "reloadは設定ファイルを読み直す操作です。サーバーを止めずに反映できる設定だけが変わります。ポート変更などは再起動が必要です。",
  "a13": "fast停止は新しい接続を受け付けず、既存の接続も切り、まだ確定していない変更を取り消してから安全に停止します。",
  "a14": "createdbは、稼働中のPostgreSQLに新しいDBを作るLinuxコマンドです。SQLのCREATE DATABASEと同じ目的です。",
  "a15": "dropdbはDBを丸ごと削除します。表とデータも消えるため、本番では実行先を慎重に確認します。",
  "a16": "pg_dumpは1つのDBの内容を復元できる形で書き出します。-dはDB名、-fは出力ファイル名です。DBを止めずに取得できます。",
  "a17": "-Fcはカスタム形式というPostgreSQL専用のバックアップ形式です。後から一部だけ選んで復元することができます。",
  "a18": "SQL形式のバックアップはCREATEやINSERTなどのSQLが入ったファイルです。psql -fで読み込むと、指定DBでそのSQLが実行されます。",
  "a19": "pg_restoreはカスタム形式などのバックアップを読み込むコマンドです。-dで戻す先のDBを指定します。",
  "a20": "pg_dumpallはサーバー内の全DBとロールなどをSQLに書き出します。pg_dumpは基本的に1つのDBだけです。",
  "a21": "pg_basebackupは、DBクラスタのファイルを復旧に使える状態でコピーするコマンドです。pg_dumpのようにSQLに変換するわけではありません。",
  "a22": "UPDATEやDELETEで不要になった古い行は、すぐにはファイルから消えません。VACUUMは、その領域を後から再利用できるようにします。",
  "a23": "ANALYZEは、表に何件あるか、どの値が多いかなどの情報を集めます。PostgreSQLはそれを参考に速い検索方法を選びます。",
  "a24": "SHOW portは、PostgreSQLが接続を受け付ける番号を表示します。通常は5432ですが、別の番号を設定できます。",
  "a25": "SHOW config_fileは、サーバー設定（postgresql.conf）が置かれている実際の場所を表示します。",
  "a26": "SHOW hba_fileは、誰がどこからどのDBへ接続できるかを決めるpg_hba.confの場所を表示します。",
  "a27": "enableは、次にLinuxが起動したときにPostgreSQLサービスも自動で起動するようにする設定です。今すぐ起動するstartとは別です。",
  "a28": "disableは自動起動の設定を解除します。今動いているPostgreSQLを停止する操作ではありません。",
  "a29": "is-enabledは自動起動の設定を確認します。今動いているかどうかはstatusなどで確認します。",
  "a30": "systemctl startはLinuxのサービス管理機能を使って今すぐPostgreSQLを起動します。自動起動設定は変わりません。",
  "a31": "systemctl stopはLinuxのサービス管理機能で今すぐPostgreSQLを止めます。次回の自動起動設定はそのままです。",
  "a32": "systemctl statusはサービスが動いているかや、直近のログなどを表示します。",
  "a33": "restartは停止してから起動します。利用中のアプリの接続は切れます。",
  "a34": "systemctl reloadは、サービスに設定の読み直しを指示します。再起動が必要な設定は反映できません。",
  "a35": "smart停止は、今つながっている利用者が全員接続を終えるまで待ちます。接続しっぱなしのアプリがあると停止も待ち続けます。",
  "a36": "immediate停止は正常終了の処理を省いて強制的に止めます。次回起動時にログを使って整合性を回復する処理が必要です。",
  "a37": "pg_ctl restartは指定クラスタを停止して再び起動します。クラスタ内の全DBに影響します。",
  "a38": "PGDATAはDBクラスタの場所を記憶しておく環境変数です。exportで設定すると、そのシェルから起動するコマンドにも渡されます。",
  "a39": "echoは文字を表示するコマンドです。$PGDATAと書くと、変数PGDATAに入っている保存先が表示されます。",
  "a40": "PGDATAにクラスタの場所が設定されていれば、pg_ctlの-Dを省略できます。-Dを明示するとそちらが優先です。",
  "a41": "createuserはPostgreSQLにログインできるロールを作るLinuxコマンドです。OSのユーザーを作る操作ではありません。",
  "a42": "dropuserはDBのロールを削除します。そのロールが表などを所有している場合は、先に所有権などを整理します。",
  "a43": "pg_config --versionはインストールされたPostgreSQLの開発用情報からバージョンを表示します。接続先のサーバー版とは限りません。",
  "a44": "pg_controldataはクラスタの管理情報をファイルから読みます。起動しているかだけでなく、チェックポイントなどの内部情報を調べられます。",
  "a45": "pg_isreadyはDBサーバーが接続を受け付けているか調べます。-pはポート番号です。実際にSQLが成功するかまでは調べません。",
  "a46": "pg_resetwalは重大な障害時に使う危険な復旧ツールです。-nは実際には変更せず、何をするかを確認するだけです。",
  "a47": "vacuumdbはLinuxからVACUUMを実行するためのコマンドです。-dはDB、-tは対象の表を指定します。",
  "a48": "-zを付けたvacuumdbはVACUUMとANALYZEを両方行います。不要領域の再利用と検索用統計の更新をまとめて行います。",
  "a49": "-lは起動時の出力をファイルに追記する指定です。server.logにメッセージが残るので、起動に失敗したときも原因を確認できます。",
  "a50": "-wのwはwait（待つ）です。起動を指示した後、接続を受け付けられる状態になるまでコマンドが待ちます。現在は-wが標準なので省略できます。逆に-Wは待ちません。",
  "a51": "-t 30は完了を待つ時間を30秒に設定します。時間内に完了しないとpg_ctlは失敗を返しますが、サーバーの処理が続く場合があります。",
  "a52": "-hは接続先のホスト、-pはポート、-Uはユーザー、-dはDB名です。別のサーバーにあるDBにも接続できます。",
  "a53": "-cの後ろにSQLを書くと、psqlを対話画面として開いたままにせず、そのSQLを実行して終了します。",
  "a54": "psql --versionは手元のpsqlアプリのバージョンを表示します。DBサーバーのバージョンはSELECT version()で調べます。",
  "a55": "\\conninfoは今つながっているDB名、ユーザー、接続先などを表示します。本番とテストを間違えていないか確認できます。",
  "a56": "スキーマとは、1つのDB内で表などをグループ分けする名前空間です。\\dnで一覧を見ます。",
  "a57": "ビューは保存したSELECT文を表のように扱う仕組みです。\\dvでビュー一覧を見ます。",
  "a58": "インデックスは本の索引のように検索を速くする仕組みです。\\diで一覧を見ます。",
  "a59": "関数はDBの中で呼び出せる処理です。\\dfで関数一覧を見ます。",
  "a60": "\\dpはテーブルなどに対して、誰がSELECTやUPDATEなどを許可されているか表示します。",
  "a61": "\\hの後にSQLの名前を書くと、そのSQLの書き方を確認できます。",
  "a62": "\\?はpsql専用コマンドのヘルプです。SQL自体の文法は\\hで確認します。",
  "a63": "\\timing onにすると、SQLを実行するたびにかかった時間が表示されます。",
  "a64": "SHOW data_directoryはDBクラスタのデータファイルが保存されるディレクトリを表示します。",
  "a65": "SHOW ALLは、接続中のサーバーの設定値をまとめて表示します。",
  "a66": "max_connectionsは同時に接続できる数の上限です。接続が多すぎてエラーになる場合の確認に使います。",
  "a67": "listen_addressesはPostgreSQLがどのネットワークアドレスで接続を待ち受けるかを決めます。",
  "a68": "timezoneは日時を扱うときのタイムゾーン設定です。日本時間とUTCのずれなどを調べられます。",
  "a69": "search_pathは、スキーマ名を省略した表名をどの順番で探すかを決めます。",
  "a70": "SETは現在の接続の設定を変えます。statement_timeoutを5秒にすると、長すぎるSQLが取り消されます。",
  "a71": "RESETはSETで変更した設定を、その設定の既定値に戻します。",
  "a72": "pg_settingsは設定の値や変更方法をSQLで調べられる一覧です。WHEREで必要な設定に絞れます。",
  "a73": "pg_reload_conf()は、SQLから設定の読み直しを指示する関数です。再起動が必要な項目は別途対応します。",
  "a74": "pg_hba_file_rulesは、認証設定の各行とエラーなどをSQLで確認できるビューです。",
  "a75": "pg_restore -lはバックアップの中身を一覧表示します。実際の復元はまだ行いません。",
  "a76": "-gはロールやテーブルスペースなど、クラスタ全体で共有する設定だけを書き出します。",
  "a77": "-sは表の作り方や制約などの定義だけを保存します。表に入っているデータは保存しません。",
  "a78": "-aは表の中身などのデータだけを保存します。復元先には対応する表の定義が必要です。",
  "a79": "-t usersを指定すると、users表を対象にバックアップします。関連する別表などがすべて自動で含まれるとは限りません。",
  "a80": "-Fdはバックアップを1つのディレクトリに複数のファイルで保存します。複数の作業を並行してバックアップする方法にも対応します。",
  "a81": "-Ftはtarアーカイブ形式を指定します。複数の内容を1つのファイルにまとめる形式です。",
  "a82": "-X streamはクラスタのコピー中に必要なWAL（変更記録）も別の接続で受け取ります。",
  "a83": "COPY TOは表のデータをCSVなどに書き出します。ファイルはDBサーバー側に保存されます。",
  "a84": "\\copyはpsqlを動かしているPC側にファイルを書き出します。サーバーのファイルに直接アクセスするCOPYとは場所が違います。",
  "a85": "COPY FROMはサーバー側に置いたファイルのデータを表へ取り込みます。",
  "a86": "archive_modeはWAL（DBの変更記録）を別の場所へ保管する仕組みを有効にする設定です。",
  "a87": "archive_commandはWALを別の保管先へ送るためのコマンド設定です。SHOWは内容を表示するだけです。",
  "a88": "CREATE ROLE ... LOGINはDBへログイン可能なアカウントをSQLで作ります。",
  "a89": "ALTER ROLEは既存ロールの属性を変更します。CREATEDBを付けるとDBを作る権限を与えます。",
  "a90": "DROP ROLEは既存のロールを削除するSQLです。表などの所有者になっている場合は先に整理が必要です。",
  "a91": "GRANTは操作を許可するSQLです。SELECTを与えると、指定したロールが表を読み取れるようになります。",
  "a92": "REVOKEは付与した権限を取り消します。他のロールを通じて同じ権限を持つ場合は別途確認が必要です。",
  "a93": "current_userは現在SQLを実行する際の有効なロール名を返します。",
  "a94": "version()は接続しているPostgreSQLサーバーのバージョンなどを表示します。",
  "a95": "information_schemaは、表や列などの情報を標準的なSQLで調べるためのビューの集まりです。",
  "a96": "pg_catalogはPostgreSQLの管理情報を持つスキーマです。pg_databaseにはDBの情報があります。",
  "a97": "VACUUM ANALYZEは不要な行の領域を再利用できるようにし、検索方法を選ぶための統計情報も更新します。",
  "a98": "VACUUM FULLは表を新しく書き直して、不要な領域をOSに返します。処理中は他の操作を強く制限するので通常は避けます。",
  "a99": "autovacuumは不要な行の領域を再利用したり統計を更新したりする自動保守の仕組みです。",
  "a100": "vacuumdb -ZはANALYZEだけを実行します。不要領域を再利用するVACUUMは行いません。",
  "a101": "サーバーが止まっているとpg_isreadyは接続できないことを示します。終了コードも確認できます。",
  "a102": "psql -fはファイルに書いてあるSQLを順番に実行します。何度も同じSQLを打たなくて済みます。",
  "a103": "\\oはpsqlの問い合わせ結果の出力先をファイルなどへ変更します。引数なしの\\oで通常表示に戻せます。",
  "a104": "\\l+はDB一覧にサイズなどの詳細も追加して表示します。",
  "a105": "log_directoryはログファイルの保存先の設定です。相対パスの場合はデータディレクトリを基準にします。",
  "a106": "logging_collectorはサーバーの標準エラー出力などを集めてログファイルに書く仕組みです。",
  "a107": "pg_settingsのcontextは設定を変更するために何が必要かを示します。例えばpostmasterなら再起動が必要です。",
  "a108": "\\copy FROMはpsqlを動かしているPC側のファイルを読み取って、DBへデータを登録します。",
  "a109": "ON_ERROR_STOP=1を設定すると、SQLファイルの途中でエラーが起きた時点でpsqlが処理を止めます。すでに確定した変更まで自動で戻す指定ではありません。",
  "a110": "pg_restore -t usersはアーカイブからusersという表を選んで復元します。必要な依存オブジェクトを別途確認します。",
  "s01": "SELECTはデータを取得するSQLです。*は全列、FROMはどの表から取るかを指定します。",
  "s02": "WHEREは行を選ぶ条件です。age >= 30なら30歳以上の行だけが残ります。",
  "s03": "ORDER BYは並べ替えです。DESCは大きい順、ASCは小さい順です。",
  "s04": "LIKEは文字のパターンに合うか調べます。%は0文字以上の任意の文字に対応します。",
  "s05": "NULLは値がない状態です。=ではなくIS NULLで調べます。",
  "s06": "COUNT(*)は条件に合う行の数を数えます。",
  "s07": "GROUP BYは同じ値を持つ行をグループにまとめ、グループごとに集計できます。",
  "s08": "HAVINGはGROUP BYでまとめた結果に条件を付けます。WHEREは集計前の行に条件を付けます。",
  "s09": "INNER JOINは両方の表に対応する行がある場合だけ結果に含めます。ONは結合条件です。",
  "s10": "LEFT JOINは左側の表の行を残します。右側に対応する行がなければ、その列はNULLになります。",
  "s11": "COALESCEは左から順に見て最初のNULLではない値を返します。",
  "s12": "副問い合わせはSQLの中に別のSELECTを書く方法です。内側の結果を外側の条件などに利用します。",
  "s13": "DISTINCTは取得結果の重複を除きます。",
  "s14": "SUMは数値の合計を返します。",
  "s15": "INSERT INTOは表に新しい行を追加します。VALUESに登録する値を書きます。",
  "s16": "UPDATEは既存の行を変更します。SETに変更内容、WHEREに対象を指定します。",
  "s17": "DELETEは表から行を削除します。WHEREを忘れると全行が対象です。",
  "s18": "BEGINで一連の処理を開始し、ROLLBACKでその間の変更を取り消します。",
  "s19": "CREATE TABLEは新しい表を作ります。列名、型、制約などを指定します。",
  "s20": "CREATE INDEXは検索のための索引を作ります。データ更新の負荷も増えることがあります。",
  "s21": "BETWEENは指定した範囲に入るかを調べます。両端も含みます。",
  "s22": "INは候補のどれかと一致するかを調べます。",
  "s23": "NOT INは候補のどれにも一致しないかを調べます。候補にNULLがあると結果に注意が必要です。",
  "s24": "IS NOT NULLは値が入っている行を選びます。",
  "s25": "ANDは両方の条件を満たす必要があります。",
  "s26": "ORは少なくとも一方の条件を満たせばよいです。",
  "s27": "LIMITは取得する最大件数を指定します。ORDER BYで順番を決めて使うと確実です。",
  "s28": "OFFSETは最初の何件を飛ばすかを指定します。",
  "s29": "AVGは平均値を求めます。NULLは平均の計算から除外されます。",
  "s30": "MINは最小値、MAXは最大値を返します。",
  "s31": "COUNT(列名)はNULLではない値を持つ行の数を返します。",
  "s32": "EXISTSは内側のSELECTで1行でも見つかると真になります。",
  "s33": "NOT EXISTSは内側のSELECTで1行も見つからない場合に真になります。",
  "s34": "CASE WHENは条件によって返す値を切り替えます。Pythonのifに近い考え方です。",
  "s35": "UNIONは複数のSELECT結果を縦につなぎ、重複する行を除きます。",
  "s36": "LOWERは文字列を小文字に変換します。",
  "s37": "UPPERは文字列を大文字に変換します。",
  "s38": "CHAR_LENGTHは文字数を返します。バイト数とは異なります。",
  "s39": "SUBSTRINGは文字列の指定位置から一部を取り出します。",
  "s40": "REPLACEは文字列の中にある指定文字列を別の文字列に置き換えます。",
  "s41": "TRIMは通常、文字列の前後の空白を除きます。",
  "s42": "CONCATは複数の値を文字列としてつなぎます。",
  "s43": "SQLでも*や+などを使って数値の計算ができます。",
  "s44": "EXTRACTは日時から年や月などの一部分を取り出します。",
  "s45": "TO_CHARは日時などを指定した書式の文字列に変換します。",
  "s46": "INTERVALは1日や1か月などの時間の長さを表します。",
  "s47": "JSONBはキーと値の組を保存できます。->>は指定キーの値を文字列として取り出します。",
  "s48": "@>は左側のJSONBが右側の内容を含むかを調べます。",
  "s49": "ビューはSELECT文に名前を付けて表のように使う仕組みです。",
  "s50": "シーケンスは連番を生成します。nextvalで次の番号を取得します。",
  "s51": "~は正規表現に一致するかを調べます。^は文字列の先頭を表します。",
  "s52": "SIMILAR TOはSQLのパターン構文で一致する文字列を調べます。",
  "s53": "COUNT(DISTINCT 列)は重複とNULLを除いた値の種類数を数えます。",
  "s54": "CROSS JOINは左と右の表の全組合せを作ります。",
  "s55": "UNION ALLは複数のSELECT結果を縦につなぎ、重複も残します。",
  "s56": "整数同士の割り算は小数部分を切り捨てます。numericに変換すると小数も扱えます。",
  "s57": "AGEは2つの日時の差を年・月・日などで返します。",
  "s58": "||は文字列を連結する演算子です。",
  "s59": "@@はJSONBに対しJSONパスの条件を評価します。",
  "s60": "SQLの真偽値にはTRUE、FALSE、値不明を示すNULLがあります。",
  "s61": "ALTER TABLE ... ADD COLUMNは既存の表に列を追加します。",
  "s62": "RENAME COLUMNは既存の列名を変更します。",
  "s63": "DROP TABLEは表そのものと中のデータを削除します。",
  "s64": "UNIQUEは同じ値の重複登録を防ぎます。通常、NULLの扱いは別です。",
  "s65": "CHECKは登録や更新する値が条件を満たすかチェックします。",
  "s66": "DEFAULTは列の値を省略したときに入れる初期値です。",
  "s67": "NOT NULLは値がない状態での登録を禁止します。",
  "s68": "REFERENCESは別の表のキーを参照する外部キー制約です。",
  "s69": "IDENTITYはIDなどの値を自動で生成する列です。",
  "s70": "マテリアライズドビューはSELECT結果を実際に保存します。内容を最新にするには更新が必要です。",
  "s71": "パーティションは大きな表を範囲などに分けて管理する仕組みです。",
  "s72": "CREATE FUNCTIONは繰り返し呼び出せる関数をDBの中に作ります。",
  "s73": "INSERT ... SELECTは別の検索結果をそのまま表に登録するSQLです。",
  "s74": "RETURNINGは更新した行などの値をその場で返します。",
  "s75": "COMMITはBEGINからの変更を確定します。確定した変更は通常ROLLBACKでは戻せません。"
};
window.LESSONS.glossary = [["クラスタ","複数のDBをまとめて管理するPostgreSQLの単位"],["ロール","DBユーザーや権限をまとめる仕組み"],["WAL","DBの変更内容を記録し、障害からの復旧に使うログ"],["PITR","バックアップと変更ログから指定時刻の状態へ戻す方法"],["MVCC","複数の利用者が同時に操作できるよう行のバージョンを管理する仕組み"],["トランザクション","複数のDB操作をまとめ、全部成功か取り消しかを扱う単位"],["スキーマ","DB内で表などをグループ分けする名前空間"],["インデックス","本の索引のように検索を速くする仕組み"],["シーケンス","IDなどに使う連番を作る仕組み"],["外部キー","他の表に対応する行があることを保証する制約"],["主キー","表の1行を一意に見分けるキー"],["autovacuum","不要領域の再利用や統計更新などを自動で行う仕組み"],["VACUUM","不要な行の領域を再利用できるようにする処理"],["ANALYZE","検索方法を選ぶためにデータの統計を集める処理"],["レプリケーション","別のサーバーなどにデータの変更を反映する仕組み"],["マテリアライズドビュー","SELECTの結果を保存して再利用する仕組み"],["ビュー","保存したSELECT文を表のように扱う仕組み"],["正規化","重複や更新漏れを減らすため表の構造を整理すること"],["NULL","値がない・不明であることを示す特別な値"],["排他ロック","他の処理が対象を同時に変更することなどを防ぐ制御"],["メタデータ","表名や列名など、データの構造を説明する情報"],["実行計画","DBがSQLを実行するために選ぶ検索・結合などの手順"],["認証","接続する人が本人か確認すること"],["ライセンス","ソフトウェアの利用・配布などの条件"],["JSONB","JSONデータを検索などに適した形式で保存する型"],["コミット","トランザクションの変更を確定する操作"],["ロールバック","まだ確定していない変更を取り消す操作"],["分離レベル","同時実行中の別処理の変更がどこまで見えるかを決める設定"],["バックアップ","障害や誤操作に備えてデータのコピーを保存すること"],["カスタム形式","pg_restoreで選択復元できるPostgreSQL専用のバックアップ形式"],["環境変数","OSのシェルなどがコマンドへ渡す設定値"],["接続プール","DB接続を何度も作らず再利用する仕組み"],["マイグレーション","アプリの変更に合わせてDBの定義を変更する作業"],["パーティション","1つの大きな表を複数の部分に分けて管理する仕組み"],["ダーティリード","別の処理がまだ確定していない変更を読み取ること"],["チェックポイント","変更済みデータをディスクへ書き出す区切り"],["表領域","DBのデータファイルの保存場所を指定する仕組み"],["トリガー","登録や更新などをきっかけにDBで自動実行する処理"],["DDL","表などの構造を作成・変更・削除するSQL"],["DML","表のデータを操作するSQL"],["OSS","ソースコードが公開され、ライセンス条件に従って利用・改変などができるソフトウェア"]];
Object.assign(window.LESSONS.usage,{"a01":"A5:SQLなどのGUIを使わず、LinuxからDBに接続してSQLを実行したいときに使います。","a11":"検証用DBを手動で起動したいときや、保守作業で止めたDBを起動するときに使います。Linuxサービスとして管理している場合は、そのサービス管理方法を使うのが一般的です。","a49":"DBが起動しない場合に使います。例えばポート番号が他のクラスタと重複していたら、その原因をログファイルから探せます。","a50":"手動ではpg_ctl startで十分です。例えば毎朝の集計バッチで「DBを起動→SQLを実行」と続けたい場合、起動成功を確認してから次へ進めます。例：PGDATA設定済みなら pg_ctl -w start && psql -d lab -f setup.sql。-wは現在の標準動作なのでバッチでも省略できます。","a51":"大量のデータを復旧するなど、起動に時間がかかる環境で待ち時間を調整するときに使います。","a53":"毎日決まった時刻に件数を確認するような自動処理で使います。例：psql -d lab -c 'SELECT COUNT(*) FROM users;'","a45":"アプリを起動する前にDBが接続を受け付けているか確認したい場合や、監視で使います。","a22":"大量に予約データを削除した後、不要な領域を再利用させたいときに使います。普段はautovacuumが自動で実施するので手動で頻繁に実行する必要はありません。","a23":"大量のExcelデータを取り込んだ後などに使います。データの分布が大きく変わると、検索の方法を選ぶための情報が古くなることがあるからです。","a98":"大量削除後、ディスクの空き容量を実際に増やす必要があるときに検討します。表を使えなくなる時間や追加のディスク容量が必要なので、通常のVACUUMとは使い分けます。","a12":"例えばpg_hba.confを変更した後、利用者の接続を切らずに認証設定を読み直したい場合に使います。","a35":"利用者が作業を終えてから止めたい保守で使います。誰かが接続したままだと止まらないので注意します。","a36":"普通の方法で止められない緊急時だけに検討します。普段の保守ではfastなどの正常停止を選びます。","a39":"別のクラスタを操作してしまわないように、作業前に保存場所を確認するときに使います。","a40":"同じクラスタを何度も操作する場合に-Dの入力を減らせます。複数クラスタがある場合は-Dを指定すると間違いにくくなります。","a16":"本番のデータをバックアップしたり、別の検証DBに復元したりするときに使います。","a46":"通常の運用では使いません。重大な破損で専門家が復旧方法を検討する際の確認用です。","q24":"DB起動後にSQLを実行するバッチなどで、起動を待つか、別に接続可能かを確認するかを考えるときに使います。","q166":"DBの起動を指示した直後にアプリを起動する場合、まだ接続できないことがあります。-wで待つか、pg_isreadyなどで別途確認します。"});

/* v2.7: UPSERT and TRUNCATE practice */
(()=>{const L=window.LESSONS;const sql=[["s76","UPSERT：既存行を更新（実務補足）","ordersにid=1、user_id=1、amount=2500をINSERTし、idが重複したら新しいamountで更新してください。","INSERT INTO ... VALUES ... ON CONFLICT (id) DO UPDATE SET amount=EXCLUDED.amount;","INSERT INTO orders (id,user_id,amount) VALUES (1,1,2500) ON CONFLICT (id) DO UPDATE SET amount=EXCLUDED.amount;",false,"SELECT * FROM orders ORDER BY id;","upsert-update"],["s77","UPSERT：新規行を追加（実務補足）","ordersにid=6、user_id=2、amount=2000をINSERTし、idが重複したら新しいamountで更新するSQLを書いてください。","ON CONFLICT (id) DO UPDATE SET amount=EXCLUDED.amount","INSERT INTO orders (id,user_id,amount) VALUES (6,2,2000) ON CONFLICT (id) DO UPDATE SET amount=EXCLUDED.amount;",false,"SELECT * FROM orders ORDER BY id;","upsert-update"],["s78","ON CONFLICT DO NOTHING（実務補足）","ordersへid=1、user_id=1、amount=9999を追加しようとし、idが重複した場合は何も変更しないSQLを書いてください。","INSERT ... ON CONFLICT (id) DO NOTHING;","INSERT INTO orders (id,user_id,amount) VALUES (1,1,9999) ON CONFLICT (id) DO NOTHING;",false,"SELECT * FROM orders ORDER BY id;","upsert-nothing"],["s79","TRUNCATE：全件削除","ordersテーブルの定義を残して、TRUNCATEで全行を削除してください。","TRUNCATE TABLE テーブル名;","TRUNCATE TABLE orders;",false,"SELECT * FROM orders ORDER BY id; SELECT * FROM users ORDER BY id;","truncate",true],["s80","TRUNCATE：ROLLBACKで取り消す","BEGINでトランザクションを開始し、ordersをTRUNCATEしてからROLLBACKで元に戻してください。","BEGIN; TRUNCATE TABLE ...; ROLLBACK;","BEGIN; TRUNCATE TABLE orders; ROLLBACK;",false,"SELECT * FROM orders ORDER BY id; SELECT * FROM users ORDER BY id;","truncate-rollback",true]],plain=["UPSERTはINSERT（追加）とUPDATE（更新）を組み合わせた操作です。ON CONFLICT (id)はidの一意制約・主キーに重複が起きたときの処理を指定します。DO UPDATE SETで既存行を更新します。EXCLUDED.amountは今回INSERTしようとした金額2500です。元のid=1の金額1200が2500に変わり、行数は5件のままです。","前の問題と同じ構文ですが、id=6はまだ存在しないので通常のINSERTが実行されます。ordersは5件から6件になります。重複しない場合にDO UPDATEは実行されません。","DO NOTHINGは指定した一意性の競合が起きた場合、その行のINSERTを行わない指定です。既にid=1があるので金額1200のままです。すべてのエラーを無視する指定ではありません。","TRUNCATEはテーブルの中身を一括で空にします。列名や型、制約などの定義は残ります。WHEREで特定行だけを選ぶことはできません。DELETEは条件を指定でき、DROP TABLEは表自体を削除します。","PostgreSQLではTRUNCATEもトランザクション内で取り消せます。BEGINからROLLBACKまでに行った削除が取り消され、ordersの5件が戻ります。COMMITで確定した後は、このROLLBACKでは戻せません。"],uses=["Excelから注文データを取り込むとき、同じIDの注文があれば金額を更新し、なければ追加したい場合に使います。先にSELECTで存在を調べてINSERT/UPDATEを分ける必要がなく、1つのSQLで重複への対処ができます。競合対象には対応する一意制約などが必要です。","日々の取込データに新規注文と既存注文が混ざる場合に便利です。追加用SQLと更新用SQLを別々に書かなくても、同じSQLを使えます。","同じデータが再送されても既存データを上書きしたくないときに便利です。たとえば処理済みIDを記録する表や、重複する取込データをスキップする処理に使います。","毎日Excelや外部システムの最新データで表の中身をすべて入れ替える「洗い替え」に使います。大量の行を消す場合に高速なことが多いですが、強い排他ロックがかかります。外部キーで参照される表は通常そのままではTRUNCATEできず、CASCADEは関連する表も空にするため慎重に扱います。","洗い替えの途中で取込が失敗した場合に元のデータへ戻せるようにするときに役立ちます。実務ではBEGIN→TRUNCATE→INSERT→確認→COMMITという流れを検討し、失敗時はROLLBACKします。処理中に他の接続が待つ可能性にも注意します。"],quiz=[["q236","UPSERT（実務補足）","主キーが重複したら既存行を更新し、重複しなければ新規登録するPostgreSQLの構文は？",["INSERT ... ON CONFLICT (...) DO UPDATE","INSERT ... ON CONFLICT DO NOTHING","TRUNCATE TABLE","UPDATEのみ"],0,"ON CONFLICT DO UPDATEは指定した一意性の競合時に既存行を更新し、競合がなければINSERTします。"],["q237","EXCLUDED（実務補足）","ON CONFLICT DO UPDATE SET amount=EXCLUDED.amount のEXCLUDED.amountは何を表しますか？",["今回INSERTしようとしたamount","既存行の更新前のamount","削除した行のamount","全行の平均額"],0,"EXCLUDEDは今回INSERTしようとした行の値を参照する特別な名前です。"],["q238","TRUNCATEとDELETE","TRUNCATEについて正しい説明はどれですか？",["表の定義を残して全行を削除し、WHEREは使えない","WHEREで任意の行だけ削除できる","表の定義も削除する","常に他の接続を妨げない"],0,"TRUNCATEは全行を一括削除します。WHEREは指定できず、強い排他ロックを取得します。"],["q239","TRUNCATEとトランザクション","PostgreSQLでBEGIN; TRUNCATE TABLE orders; ROLLBACK; を実行した場合、元のordersの行はどうなりますか？",["元に戻る","常に消えたまま","表の定義も消える","全DBが初期化される"],0,"PostgreSQLのTRUNCATEはトランザクション内でROLLBACKできます。"],["q240","TRUNCATE RESTART IDENTITY","TRUNCATE TABLE orders RESTART IDENTITYのRESTART IDENTITYの意味は？",["対象表の列が所有するシーケンスを開始値に戻す","クラスタを再起動する","すべてのDBのシーケンスを戻す","表の定義を削除する"],0,"RESTART IDENTITYは対象表の列が所有するシーケンスを再初期化します。既定はCONTINUE IDENTITYです。"]],reasons=[["追加と更新の両方に対応します。","競合した行は更新せずスキップします。","表の全行を削除します。","存在しない行をINSERTすることはできません。"],["新しく投入しようとした値を参照します。","既存行の値は表名や別名で参照します。","削除処理を表すものではありません。","集計関数ではありません。"],["表を空にする処理です。","条件付き削除にはDELETEを使います。","表自体を消すのはDROP TABLEです。","強いロックのため他の操作が待つことがあります。"],["未確定のTRUNCATEは取り消せます。","COMMIT前なので取り消せます。","TRUNCATEは表の定義を残します。","対象表の操作であり、全DB初期化ではありません。"],["自動採番に使う所有シーケンスを開始値へ戻します。","サーバー再起動とは無関係です。","対象表の列が所有するものに限定されます。","表の定義は残ります。"]],quses=["Excelから注文データを取り込むとき、同じIDの注文があれば金額を更新し、なければ追加したい場合に使います。先にSELECTで存在を調べてINSERT/UPDATEを分ける必要がなく、1つのSQLで重複への対処ができます。競合対象には対応する一意制約などが必要です。","既存注文を新しい金額で上書きするときに使います。","定期データ取込前に作業用テーブルを空にする場合に使います。","全件洗い替えの途中で取込エラーが出たとき、元データに戻すために利用できます。","テスト用データを全消去して採番も最初からやり直すときなどに使います。本番でIDを再利用する必要があるかは慎重に判断します。"];sql.forEach((t,j)=>{const ch=t[0]==='s80'?L.chapters.sql.s75:L.chapters.sql.s17;const i=L.sql.findLastIndex(x=>L.chapters.sql[x[0]]===ch);L.sql.splice(i+1,0,t);L.chapters.sql[t[0]]=ch;L.beginner[t[0]]=plain[j];L.usage[t[0]]=uses[j]});quiz.forEach((t,j)=>{const trans=t[0]==='q239';const ch=trans?L.chapters.quiz.q235:L.chapters.quiz.q207;const i=L.quiz.findLastIndex(x=>L.chapters.quiz[x[0]]===ch);L.quiz.splice(i+1,0,t);L.chapters.quiz[t[0]]=ch;L.quizTopics[t[0]]=trans?'S3.3':'S3.1';L.quizExplanations[t[0]]=reasons[j];L.usage[t[0]]=quses[j]})})();

/* v2.8: OS user / psql session workflow */
(()=>{const L=window.LESSONS;const rows=[[["a111","OSユーザー切替","現在はubuntuというLinuxユーザーです。postgresユーザーのログインシェルへ切り替えてください。まだDBには接続しません。","sudo -i -u ユーザー名（-iuとまとめて書けます）。","sudo -iu postgres","sudoは別のOSユーザーとしてコマンドを実行するLinuxの仕組み。-iはログインシェル、-uは対象のOSユーザー。","shell","os-original"],"sudo -iu postgresはLinuxの操作ユーザーをpostgresへ切り替えます。sudoは権限のあるユーザーが別のユーザーとして実行する仕組み、-iはログイン時の環境を使うシェルを開始、-u postgresはOSユーザーを指定します。DB接続はまだ行っていません。","LinuxでPostgreSQLのデータディレクトリを所有するOSユーザーとして管理作業をするときに使います。sudo権限とpostgresというOSユーザーが必要です。認証方法や環境によっては切替不要です。RDSなどのマネージドDBでは通常この操作はしません。","a43","試験範囲外・実務向け"],[["a112","OSユーザー確認","postgresに切り替え済みです。現在のLinuxの実効ユーザー名を表示してください。","whoamiコマンド。","whoami","whoamiは現在の実効OSユーザー名を表示します。","shell"],"whoamiは今Linux上でどのOSユーザーとして操作しているかを表示します。postgresと出てもDBに接続した意味ではありません。","作業前にユーザーを間違えていないか確認します。DB側のユーザーはpsqlでSELECT current_user;を実行して確認します。","a43","試験範囲外・実務向け"],[["a113","psql内でSQLファイル実行","lab DBにpsqlで接続済みです。準備済みのquery.sqlを読み込んで実行し、接続を維持してください。","psqlのメタコマンド \\i（include）を使います。","\\i query.sql","\\iはpsql内でSQLファイルを実行し、接続を維持します。","psql"],"\\i query.sqlはpsql内でファイルを読み込んでSQLを実行します。query.sqlはpsqlを起動した端末側にあるファイルです。実行後はlab=#に戻ります。セミコロンは不要です。","手動でSQLファイルの動作を確認したり、接続を保ったまま追加のSQLを実行したいときに使います。シェルから実行して終了するpsql -d lab -f query.sqlとは入力場所・接続終了の有無が違います。","a103",null],[["a114","元のOSユーザーに戻る","psqlは終了済みです。sudoで開始したpostgresのログインシェルを終了し、元のubuntuユーザーに戻ってください。","シェルを終了するexit。","exit","exitは現在のシェルを終了します。sudoで起動したシェルなら元のシェルへ戻ります。","shell","os-switched"],"exitはLinuxの現在のシェルを終了します。sudo -iu postgresで開始したシェルを抜けると元のubuntuユーザーに戻ります。psqlを閉じる\\qとは別です。PostgreSQLサーバーも停止しません。","管理作業が終わったらpostgresの権限で操作し続けないよう、元のユーザーへ戻るために使います。最初から通常のシェルにいる場合はexitで端末セッションが終了することがあります。","a08","試験範囲外・実務向け"]];function move(id,after){const i=L.admin.findIndex(t=>t[0]===id),t=L.admin.splice(i,1)[0];L.admin.splice(L.admin.findIndex(x=>x[0]===after)+1,0,t);L.chapters.admin[id]=L.chapters.admin[after]}move('a53','a102');move('a08','a103');move('a41','a90');move('a42','a41');move('a12','a107');move('a108','a84');for(const [t,plain,use,anchor,scope] of rows){const ch=L.chapters.admin[anchor];const i=L.admin.findIndex(x=>x[0]===anchor);L.admin.splice(t[0]==='a114'?i+1:i,0,t);L.chapters.admin[t[0]]=ch;L.beginner[t[0]]=plain;L.usage[t[0]]=use;if(scope)L.adminScope[t[0]]=scope}L.usage.a102='バッチや定期実行でファイル内のSQLをまとめて実行するときに使います。psql -d lab -f query.sql はLinuxから実行し、自動でDB接続→SQL実行→切断します。psql接続中なら \\i query.sql を使います。';L.beginner.a102='-fはファイルに書いてあるSQLを実行する指定です。まだpsqlへ接続していなくても、このコマンドが接続して実行し、自動で終了します。query.sqlはpsqlを実行する端末側のファイルです。';})();
